     1	import en from './en';
     2	import es from './es';
     3	import esES from './es-ES';
     4	import type {FlatTranslationsObject, TranslationDeepObject} from './types';
     5	
     6	/**
     7	 * Converts an object to it's flattened version.
     8	 *
     9	 * Ex:
    10	 * Input: { common: { yes: "Yes", no: "No" }}
    11	 * Output: { "common.yes": "Yes", "common.no": "No" }
    12	 */
    13	// Necessary to export so that it is accessible to the unit tests
    14	// eslint-disable-next-line rulesdir/no-inline-named-export
    15	export function flattenObject<TTranslations>(obj: TranslationDeepObject<TTranslations>): FlatTranslationsObject {
    16	    const result: Record<string, unknown> = {};
    17	
    18	    const recursive = (data: TranslationDeepObject, key: string): void => {
    19	        // If the data is a function or not a object (eg. a string or array),
    20	        // it's the final value for the key being built and there is no need
    21	        // for more recursion
    22	        if (typeof data === 'function' || Array.isArray(data) || !(typeof data === 'object' && !!data)) {
    23	            result[key] = data;
    24	        } else {
    25	            let isEmpty = true;
    26	
    27	            // Recursive call to the keys and connect to the respective data
    28	            Object.keys(data).forEach((k) => {
    29	                isEmpty = false;
    30	                recursive(data[k] as TranslationDeepObject, key ? `${key}.${k}` : k);
    31	            });
    32	
    33	            // Check for when the object is empty but a key exists, so that
    34	            // it defaults to an empty object
    35	            if (isEmpty && key) {
    36	                result[key] = '';
    37	            }
    38	        }
    39	    };
    40	
    41	    recursive(obj, '');
    42	    return result as FlatTranslationsObject;
    43	}
    44	
    45	export default {
    46	    en: flattenObject(en),
    47	    es: flattenObject(es),
    48	    // eslint-disable-next-line @typescript-eslint/naming-convention
    49	    'es-ES': flattenObject(esES),
    50	};
