   309	/**
   310	 * Initialize expense info
   311	 * @param reportID to attach the transaction to
   312	 * @param policy
   313	 * @param isFromGlobalCreate
   314	 * @param iouRequestType one of manual/scan/distance
   315	 */
   316	function initMoneyRequest(
   317	    reportID: string,
   318	    policy: OnyxEntry<OnyxTypes.Policy>,
   319	    isFromGlobalCreate: boolean,
   320	    currentIouRequestType: IOURequestType | undefined,
   321	    newIouRequestType: IOURequestType,
   322	) {
   323	    // Generate a brand new transactionID
   324	    const newTransactionID = CONST.IOU.OPTIMISTIC_TRANSACTION_ID;
   325	    const currency = policy?.outputCurrency ?? currentUserPersonalDetails?.localCurrencyCode ?? CONST.CURRENCY.USD;
   326	    // Disabling this line since currentDate can be an empty string
   327	    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   328	    const created = currentDate || format(new Date(), 'yyyy-MM-dd');
   329	
   330	    // in case we have to re-init money request, but the IOU request type is the same with the old draft transaction,
   331	    // we should keep most of the existing data by using the ONYX MERGE operation
   332	    if (currentIouRequestType === newIouRequestType) {
   333	        // so, we just need to update the reportID, isFromGlobalCreate, created, currency
   334	        Onyx.merge(`${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${newTransactionID}`, {
   335	            reportID,
   336	            isFromGlobalCreate,
   337	            created,
   338	            currency,
   339	            transactionID: newTransactionID,
   340	        });
   341	        return;
   342	    }
   343	
   344	    const comment: Comment = {};
   345	
   346	    // Add initial empty waypoints when starting a distance expense
   347	    if (newIouRequestType === CONST.IOU.REQUEST_TYPE.DISTANCE) {
   348	        comment.waypoints = {
   349	            waypoint0: {keyForList: 'start_waypoint'},
   350	            waypoint1: {keyForList: 'stop_waypoint'},
   351	        };
   352	        if (!isFromGlobalCreate) {
