   358	    // Store the transaction in Onyx and mark it as not saved so it can be cleaned up later
   359	    // Use set() here so that there is no way that data will be leaked between objects when it gets reset
   360	    Onyx.set(`${ONYXKEYS.COLLECTION.TRANSACTION_DRAFT}${newTransactionID}`, {
   361	        amount: 0,
   362	        attendees: IOUUtils.formatCurrentUserToAttendee(currentUserPersonalDetails, reportID),
